import{_ as o,C as s,o as r,c as _,j as i,a as t,E as p,ag as a}from"./chunks/framework.DUTPmUpA.js";const n="/_assets/HandsomeImpossibleHyena.jQ4e4uD4.mp4",d="/_assets/OptimalRichDeviltasmanian.a09Ehhdd.mp4",u="/_assets/ClumsyImpishGardensnake.BNqB6crW.mp4",c="/_assets/FewLeftAcornbarnacle.CKC9vq0J.mp4",m="/_assets/FinishedRewardingBactrian.CNQ6JL-a.mp4",f="/_assets/DisastrousRecentBaldeagle.BzYhn5-0.mp4",w=JSON.parse('{"title":"Вулкан Частица","description":"","frontmatter":{"title":"Вулкан Частица","author":"Noya","steamId":"76561198046984233","date":"07.02.2015"},"headers":[],"relativePath":"assets/particles/volcano-particle.md","filePath":"assets/particles/volcano-particle.md"}'),b={name:"assets/particles/volcano-particle.md"};function T(g,l,C,P,S,v){const e=s("StaticVideo");return r(),_("div",null,[l[0]||(l[0]=i("ul",null,[i("li")],-1)),l[1]||(l[1]=i("h1",{id:"вулкан-частица",tabindex:"-1"},[t("Вулкан Частица "),i("a",{class:"header-anchor",href:"#вулкан-частица","aria-label":'Permalink to "Вулкан Частица"'},"​")],-1)),l[2]||(l[2]=i("p",null,[t("Здесь я объясню, как изменить уже существующие частицы для создания "),i("a",{href:"https://github.com/MNoya/DotaCraft/blob/master/scripts/npc/abilities/firelord_volcano.txt",target:"_blank",rel:"noreferrer"},"Volcano ability"),t(".")],-1)),l[3]||(l[3]=i("p",null,[t("Я не буду создавать частицы с нуля или углубляться в их возможности, поэтому обязательно прочитайте замечательный "),i("a",{href:"/assets/particles/particle-basics"},"Particle Creation Series"),t(" от kritth, чтобы получить более глубокое понимание, чем просто этот пример.")],-1)),p(e,{path:n}),l[4]||(l[4]=a('<br><p>Сначала нам нужен земной конус вулкана радиусом ~250 AoE. Для этого есть полезная система частиц <code>espirit_spawn.vpcf</code>, откройте ее.</p><p>Перейдите к его первому дочернему элементу <code>_ground</code>.</p><p>Я хочу скрыть твердую модель, потому что для этого заклинания потребуется столкновение с вулканом, порождающее <a href="https://github.com/MNoya/DotaCraft/blob/master/scripts/npc/units/firelord_volcano.txt" target="_blank" rel="noreferrer">simple volcano unit</a>. Итак, в основной частице отключите модель рендеринга.</p><p>Теперь нам нужно настроить его дочерний элемент в соответствии с размером и продолжительностью родительского элемента, заставив его зацикливаться на камнях.</p><ul><li>Постоянно добавлять излучение</li><li>Отключите базовое движение и простое затухание альфа-канала.</li><li>Отключить 2 переназначения количества частиц на скалярное.</li><li>Радиус от 16 до 25, место на земле сделать 0</li><li>Случайное время жизни, максимальное значение измените на 0. Это заставит Землю двигаться постоянно и хаотично.</li></ul><br><p>Давайте повторим те же действия с другими детьми, чтобы эффект пыли и мусора повторился.</p><ul><li>На <code>_groundburst</code>: <ul><li>Постоянно добавляйте Emit.</li><li>Поскольку больше частиц всегда лучше, мы хотим, чтобы запускалось больше мусора. Для этого перейдите к его базовым свойствам, отфильтруйте по максимальному значению и удвойте значение максимального количества частиц.</li><li>Затем мгновенно перейдите к Emit, в числе, которое нужно испустить, также удвойте это значение.</li><li>Также увеличьте размер радиуса запускаемых частиц, перейдя в случайный радиус инициализатора и установив минимальное и максимальное значения 0,1 и 0,5.</li><li>Наконец, измените модель камня на более темную, отобразите модель на <code>bad_barracks_stones003.vmdl</code>.</li></ul></li></ul><p>Сейчас это выглядит так (я забыл скрыть модель для этого предварительного просмотра)</p>',10)),p(e,{path:d}),l[5]||(l[5]=a("<br><p>Переходя к <code>_grounddustbdust</code>, мы видим, что частица уже постоянно имеет Emit, но на самом деле она не зацикливается, как нам хотелось бы, а просто испускает одно облако.</p><ul><li>Измените Emit непрерывно на продолжительность излучения 0.</li><li>Отключите преобразование скаляра в вектор в нижней части функций инициализатора (это избавит от черных облаков).</li><li>Я также хочу, чтобы дым поднимался выше, для этого измените третье значение Z базового движения на 400 с исходных 200.</li></ul><p>Теперь система частиц как бы заполняет всю частицу пылью, поэтому мы делаем следующее:</p><ul><li>В Initializer Radius Random измените максимальный радиус с 40 на 15.</li><li>В базовых свойствах уменьшите максимальное количество частиц с 36 до 20.</li></ul><p>Наконец мы закончили основную основу вулкана:</p>",6)),p(e,{path:u}),l[6]||(l[6]=a("<p>Поскольку я не хочу или не нуждаюсь в дополнительных контрольных точках, я позабочусь о том, чтобы все контрольные точки этой системы частиц были привязаны к CP0.</p><p>Зайдя в основную систему частиц и переместив CP1, мы видим, что пылевой и наземный взрыв привязан к CP1. Мы хотим, чтобы они были на уровне CP0 для простоты.</p><p>Чтобы узнать, какие поля имеют какую контрольную точку, наведите на них курсор:</p><p>Теперь перейдите в эту позицию по кольцу, измените CP на 0, и готово.</p><p>Повторите тот же процесс с частицей наземного взрыва.</p><hr><p>Now, let&#39;s add fire to it!</p><br><p>Back to the particle editor, open the recently forked, sf_fire_arcana_wings system</p><ul><li><p>Скройте эффекты крыльев, отключив рендеринг модели крыльев.</p></li><li><p>Завести нового ребенка</p></li><li><p>Добавьте созданную ранее пользовательскую систему espirit_spawn.</p></li></ul><p>— Измените первые 3 дочерние частицы sf_fire_arcana_wings, чтобы они излучали непрерывно, как раньше.</p><ul><li><p>Зайдя в sf_fire_arcana_wings_smoke_body, вы можете увидеть, что там скопировано много дочерних элементовwing_rope, каждый из этих дочерних элементов имеет разное положение на земле.</p><p>Давайте оставим только 1 посередине и отключим остальные, одновременно заставляя его излучать непрерывно. <code>_wings_rope</code> уже настроен на непрерывное излучение, но имеет ограниченную продолжительность излучения до 2,0, измените ее на 0.</p><p>Также отключите начальные скаляры 2nd Remap, чтобы правильно получить постоянную частицу.</p></li><li><p>Теперь зайдите в веревку_detail и сделайте то же самое: продолжительность выброса 0, начальный скаляр Remap отсутствует. Также отключите вектор шума, из-за которого частица через некоторое время заикается.</p></li><li><p>Вернитесь кwings_smoke и отключите инициализатор: случайное смещение изменения позиции, так как это не позволяет веревке начинаться в центре CP1.</p></li><li><p>Для <code>_beams</code> также сделайте их постоянными, отключите эффект остановки после продолжительности, длительность непрерывного излучения должна быть равна 0. Уменьшите максимальное количество частиц до трети его значения, 36-&gt;12. Измените смещение на 0,0,10.</p></li><li><p>В Grow_rope добавьте Emit непрерывно и отключите инициализаторы для переназначения количества частиц на скалярное. в его дочернем элементе веревки_glow нужно только изменить продолжительность излучения на 0.</p></li><li><p><code>_ember</code> продолжительность излучения 0 также</p></li><li><p>Постоянно добавлять эмиссию в <code>_core</code>.</p></li><li><p><code>_souls_hands_pnt</code> должен быть прикреплен к рукам теневых злодеев, но наша модель не использует это, поэтому нам нужно его немного изменить, в основном делая то же самое, что и раньше (изменение или добавление постоянного излучения, удаление вещей, которые останавливают его и т. д.)</p></li><li><p>Я отключаю <code>_souls_hands_tail</code>, потому что это уже слишком много шума, и заменяю притяжение к контрольной точке базовым движением Z, требованием 50, чтобы выглядело так, будто свет исходит из центра и течет вверх.</p></li></ul><p>Теперь, после всего этого бардака:</p>",13)),p(e,{path:c}),l[7]||(l[7]=a("<hr><p>После того, как ядро вулкана готово, пришло время добавить несколько валунов, исходящих из центра, во все точки в радиусе 500 АОЕ способности.</p><p>Это будет дополнительная система частиц, которую я хочу повторять в выбранном мной интервале времени в способности, поэтому это будет всего лишь один экземпляр, и я могу легко использовать ThinkInterval + FireEffect. Для этой цели я буду использовать модифицированный warlock_rain_of_chaos_explosion.vpcf с sf_fire_arcana_shadowraze.</p><ul><li><p>Сначала добавьте детей, разрушающих тень, и увеличьте продолжительность большинства эффектов взрыва, чтобы после взрыва они длились немного дольше.</p></li><li><p><code>_char</code> увеличил случайное время жизни до 4 и 5. Дочерний char_fire удвоил продолжительность непрерывного излучения.</p></li><li><p>Длительность выполнения <code>_end_smoke</code> до 3,0 секунды.</p></li></ul><p>Вот и все, что касается Shadowraze, теперь камни движутся медленнее, живут дольше и имеют анимацию в конце, когда они падают на землю!</p><p>О хаосе_взрыве</p><p>Нам нужно изменить некоторые функции инициализатора, чтобы уменьшить скорость и продлить срок службы камней.</p><ul><li>Отключите шкалу радиуса, чтобы камни не уменьшались в размерах.</li><li>Отключите затухание продолжительности жизни, чтобы частицы не исчезали по истечении определенного времени.</li><li>Добавьте следующий оператор, чтобы частицы исчезали при ударе о землю: <strong>Отбрасывать при пересечении плоскости</strong>, по умолчанию сохранять нормальную плоскость 0,0,1.</li><li>Также добавьте случайный инициализатор изменения смещения позиции, чтобы они начинались немного выше по оси z, чтобы некоторые камни не удалялись раньше. Я поставил минимальное и максимальное смещение равным 20.</li><li>Увеличьте количество испускаемых частиц, число излучаемых = 36. Также сделайте так, чтобы они не появлялись все в одном кадре, максимальное излучение за кадр = 1.</li><li>Уменьшите скорость на позиции вдоль кольца оператора, минимальная начальная скорость = 800 и максимальная = 100.</li></ul><p>Результат:</p>",9)),p(e,{path:m}),l[8]||(l[8]=i("hr",null,null,-1)),l[9]||(l[9]=i("p",null,"И последнее, но не менее важное: при нанесении урона юниту будет воспроизводиться еще один эффект. Теперь изменение частиц/custom/sf_fire_arcana_base_attack_impact.vpcf возможно после его декомпиляции ранее, а создание более крупного и яркого взрыва должно быть тривиальным с тем, что я объяснил в предыдущих модификациях частиц.",-1)),l[10]||(l[10]=i("p",null,"Я также добавлю сюда эффект lone_druid_bear_entangle_ground_soil_cauldron, чтобы оставить след там, где камень повредил врага.",-1)),l[11]||(l[11]=i("p",null,"Наконец, после того, как мы собрали вместе частицу со способностью...",-1)),p(e,{path:f}),l[12]||(l[12]=i("hr",null,null,-1)),l[13]||(l[13]=i("p",null,"Я надеюсь, что это не такая уж большая путаница для воспроизведения, и между бессвязной болтовней спрятана полезная информация. Если вы обнаружите какие-либо проблемы или у вас есть предложения, не стесняйтесь внести свой вклад в эту статью.",-1))])}const h=o(b,[["render",T]]);export{w as __pageData,h as default};
